CREATE TEMPORARY VIEW search_guide_be_log_${grass_region_without_quote} AS
SELECT

    FROM_JSON(GET_JSON_OBJECT(message, '$.filtered_keywords.AdminBlacklistFilter'), 'ARRAY<STRING>') AS admin_blacklist_filter
FROM 
    search_data.shopping_guide_funnel_log_1h_raw
WHERE
    grass_region = ${grass_region}
    AND regional_date BETWEEN ${local_date} AND date_add(${local_date}, 1)
    AND date(date_timezone_convert(regional_date,regional_hour,'SG',grass_region,"yyyy-MM-dd")) = ${local_date};

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_guide_blacklist_metrics_1d
PARTITION (
    grass_region=${grass_region},
    local_date = ${local_date}
)
SELECT
    GET_JSON_OBJECT(detail,'$.extra_info.blacklist_word') as blacklist_word
    ,GET_JSON_OBJECT(detail,'$.keyword') as filtered_keyword
    ,GET_JSON_OBJECT(detail,'$.reason') as reason
    ,GET_JSON_OBJECT(detail,'$.queue') as queue
    ,GET_JSON_OBJECT(detail,'$.filter_name') as filter_name
    ,GET_JSON_OBJECT(detail,'$.rule_type') as rule_type
    ,COUNT(1) AS intercept_cnt
FROM 
    search_guide_be_log_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(admin_blacklist_filter) AS detail
GROUP BY 
    1,2,3,4,5,6;
